/* Differential tests use mGBA only as an external reference renderer. Fixtures
 * are synthetic RAM/register values generated by ppu_synthetic.py, not ROM data. */
#include <mgba/internal/gba/renderers/video-software.h>
#include "ppu.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static struct GBAVideoSoftwareRenderer oracle;
static uint16_t io[PPU_IO_SIZE / 2], pal[PPU_PALETTE_SIZE / 2];
static uint16_t vram[PPU_VRAM_SIZE / 2];
static union GBAOAM oam;
static uint32_t expected[PPU_WIDTH * PPU_HEIGHT];
static uint32_t actual[PPU_WIDTH * PPU_HEIGHT];
static struct {unsigned line, offset, value;} events[512];

static unsigned get16(FILE *f)
{
    unsigned a = (unsigned)fgetc(f), b = (unsigned)fgetc(f);
    if (a > 255 || b > 255) { fprintf(stderr, "short event\n"); exit(2); }
    return a | (b << 8);
}

int main(int argc, char **argv)
{
    Ppu ppu;
    PpuMemory m = {(uint8_t *)io, (uint8_t *)pal, (uint8_t *)vram, (uint8_t *)&oam};
    unsigned count = 0, next = 0, y, x, reg, mismatches = 0;
    FILE *in;
    if (argc < 2 || argc > 3) { fprintf(stderr, "usage: ppu_oracle fixture.bin [reference.ppm]\n"); return 2; }
    in = fopen(argv[1], "rb");
    if (!in) { perror(argv[1]); return 2; }
    if (fread(io, 1, sizeof(io), in) != sizeof(io) || fread(pal, 1, sizeof(pal), in) != sizeof(pal) ||
        fread(vram, 1, sizeof(vram), in) != sizeof(vram) || fread(&oam, 1, sizeof(oam), in) != sizeof(oam)) {
        fprintf(stderr, "short fixture\n"); return 2;
    }
    while (!feof(in)) {
        int first = fgetc(in);
        if (first == EOF) break;
        ungetc(first, in);
        if (count == 512) return 2;
        events[count].line = get16(in);
        events[count].offset = get16(in);
        events[count].value = get16(in);
        if (events[count].line >= 160 || events[count].offset >= 0x56 || (events[count].offset & 1)) return 2;
        ++count;
    }
    fclose(in);
    GBAVideoSoftwareRendererCreate(&oracle);
    oracle.outputBuffer = expected;
    oracle.outputBufferStride = PPU_WIDTH;
    oracle.d.palette = pal;
    oracle.d.vram = vram;
    oracle.d.oam = &oam;
    oracle.d.init(&oracle.d);
    oracle.d.writeVideoRegister(&oracle.d, 0, io[0]);
    oracle.d.writeVideoRegister(&oracle.d, 2, io[1]);
    for (reg = 8; reg <= 0x54; reg += 2) {
        if (reg == 0x4e) continue;
        oracle.d.writeVideoRegister(&oracle.d, reg, io[reg / 2]);
    }
    /* One warm-up frame establishes window latches for wrapped vertical ranges. */
    for (y = 0; y < PPU_HEIGHT; ++y) oracle.d.drawScanline(&oracle.d, y);
    oracle.d.finishFrame(&oracle.d);
    ppu_begin_frame(&ppu, &m);
    for (y = 0; y < PPU_HEIGHT; ++y) {
        while (next < count && events[next].line == y) {
            reg = events[next].offset;
            io[reg / 2] = events[next].value;
            oracle.d.writeVideoRegister(&oracle.d, reg, io[reg / 2]);
            ppu_write_register(&ppu, &m, reg, 2);
            ++next;
        }
        oracle.d.drawScanline(&oracle.d, y);
        ppu_render_scanline_rgb888(&ppu, &m, y, actual + y * PPU_WIDTH);
    }
    for (y = 0; y < PPU_HEIGHT; ++y) {
        for (x = 0; x < PPU_WIDTH; ++x) {
            uint32_t a = actual[y * PPU_WIDTH + x];
            uint32_t b = expected[y * PPU_WIDTH + x] & 0xffffff;
            if (a == b) continue;
            if (mismatches < 4) fprintf(stderr, "(%u,%u): port=%06x mgba=%06x\n", x, y, a, b);
            ++mismatches;
        }
    }
    if (mismatches) {
        char filename[1024];
        unsigned i;
        FILE *out;
        snprintf(filename, sizeof(filename), "%s.diff.ppm", argv[1]);
        out = fopen(filename, "wb");
        if (!out) return 2;
        fprintf(out, "P6\n480 160\n255\n");
        for (y = 0; y < PPU_HEIGHT; ++y) for (i = 0; i < 2; ++i) for (x = 0; x < PPU_WIDTH; ++x) {
            uint32_t c = i ? expected[y * PPU_WIDTH + x] : actual[y * PPU_WIDTH + x];
            fputc(c & 255, out); fputc((c >> 8) & 255, out); fputc((c >> 16) & 255, out);
        }
        fclose(out);
    }
    if (argc == 3) {
        FILE *out = fopen(argv[2], "wb");
        if (!out) { perror(argv[2]); return 2; }
        fprintf(out, "P6\n240 160\n255\n");
        for (y = 0; y < PPU_HEIGHT; ++y) for (x = 0; x < PPU_WIDTH; ++x) {
            uint32_t c = expected[y * PPU_WIDTH + x];
            fputc(c & 255, out); fputc((c >> 8) & 255, out); fputc((c >> 16) & 255, out);
        }
        if (fclose(out)) return 2;
    }
    printf("%u\n", mismatches);
    oracle.d.deinit(&oracle.d);
    return mismatches ? 1 : 0;
}
